<?php
require __DIR__.'/protection-bootstrap.php';
$variant=$argv[1]??'green';if(!in_array($variant,['red','green'],true))throw new RuntimeException('Use an explicit isolated review fixture.');
$src='director_it_1018/review-'.$variant;$dst='director_rt_1018/review-'.$variant;
foreach([$src,$dst,$src.'/send',$src.'/policy-a',$src.'/policy-b']as$ds){$probe=runProcess('zfs',['list','-H','-o','name',$ds]);if($probe['code']!==0)nativeCommand(['create',$ds]);}
function reviewDefinition($id,$source,$target,$extra=[]){$r=zfsmSyncoidJob(array_replace(['id'=>$id,'source'=>$source,'target'=>$target,'source_guid'=>zfsmReadIdentity($source)['guid']],$extra));$s=zfsmProtectionReadStore();$s['replications'][$id]=$r;zfsmProtectionWriteStore($s);return $r;}
nativeCheck('replication startup waits for an existing native mutation lock',function()use($src,$dst){
 $r=reviewDefinition('c1',$src.'/send',$dst.'/lock');$j=zfsmNewProtectionJob('replication',$r);zfsmJobAtomicWrite(zfsmJobFile($j['id']),$j);$lock=fopen($GLOBALS['plugin_lock'],'c');nativeExpect(flock($lock,LOCK_EX|LOCK_NB),'Cannot acquire test mutation lock');
 try{zfsmRunProtectionJob($j);$after=zfsmReadJob($j['id']);nativeExpect($after['state']==='queued','Replication bypassed native mutation lock: '.$after['state']);return ['state'=>$after['state'],'kernel_flock'=>true];}finally{flock($lock,LOCK_UN);fclose($lock);zfsmProtectionCancel($j['id']);}
});
nativeCheck('native Sanoid executes its immutable config after another preview prepares',function()use($src){
 $a=$src.'/policy-a';$b=$src.'/policy-b';$p=zfsmSanoidPolicy(['id'=>'c2','dataset'=>$a,'frequently'=>1,'hourly'=>1,'autoprune'=>false]);$first=zfsmSanoidPrepare($p,[$a]);$p['dataset']=$b;$second=zfsmSanoidPrepare($p,[$b],true);$d=zfsmProtectionRequire(false);$result=runProcess($d['sanoid']['path'],array_merge($first,['--take-snapshots']));nativeExpect($result['code']===0,$result['output']);$afterA=zfsmSanoidInventory($a);$afterB=zfsmSanoidInventory($b);nativeExpect(count($afterA['snapshots'])>0,'Intended policy did not snapshot');nativeExpect(!$afterB['snapshots'],'Uncommitted preview scope was snapshotted');return ['different_configdirs'=>$first[0]!==$second[0],'intended_snapshots'=>array_keys($afterA['snapshots']),'preview_scope_snapshots'=>0];
});
nativeCheck('partial initial receiver GUID persists then native resume and replacement guard work',function()use($src,$dst,$base){
 $source=$src.'/send';$target=$dst.'/partial';$mount=nativeCommand(['get','-H','-o','value','mountpoint',$source]);$file=$mount.'/review-payload.bin';if(!is_file($file)){$h=fopen($file,'wb');for($i=0;$i<32;$i++)fwrite($h,random_bytes(262144));fclose($h);}
 $r=reviewDefinition('c3',$source,$target,['bandwidth'=>'256k']);$j=zfsmNewProtectionJob('replication',$r);zfsmJobAtomicWrite(zfsmJobFile($j['id']),$j);$process=proc_open(['/usr/bin/php',__DIR__.'/protection-one.php',$j['id']],[0=>['file','/dev/null','r'],1=>['file',$base.'/review-receiver.log','a'],2=>['redirect',1]],$pipes);nativeExpect(is_resource($process),'Cannot start isolated worker');
 $deadline=microtime(true)+120;$observed=null;
 while(microtime(true)<$deadline){$saved=zfsmProtectionReadStore()['replications']['c3'];if($saved['target_guid']!==null){$observed=$saved['target_guid'];break;}if(!proc_get_status($process)['running'])break;usleep(200000);}
 zfsmProtectionCancel($j['id']);$deadline=microtime(true)+60;while(proc_get_status($process)['running']&&microtime(true)<$deadline)usleep(200000);nativeExpect(!proc_get_status($process)['running'],'Owned cancellation did not finish');proc_close($process);
 $stopped=zfsmReadJob($j['id']);$saved=zfsmProtectionReadStore()['replications']['c3'];$guid=nativeCommand(['get','-H','-o','value','guid',$target]);nativeExpect($observed===$guid&&$saved['target_guid']===$guid,'Receiver GUID was not durable during transfer');nativeExpect($stopped['verified_outcome']==='interrupted',json_encode($stopped['verification']));$token=nativeCommand(['get','-H','-o','value','receive_resume_token',$target]);nativeExpect($token!=='-','No retained native resume token');
 $s=zfsmProtectionReadStore();$s['replications']['c3']['bandwidth']='1m';zfsmProtectionWriteStore($s);$resumed=nativeJob('replication','c3');nativeExpect($resumed['verified_outcome']==='completed',json_encode($resumed['verification']));nativeExpect(zfsmReadIdentity($target)['guid']===$guid,'Resume changed receiver GUID');
 $retained=$target.'-retained';nativeCommand(['rename',$target,$retained]);nativeCommand(['create','-o','canmount=off',$target]);$replacement=zfsmReadIdentity($target)['guid'];$blocked=nativeJob('replication','c3');nativeExpect($blocked['state']==='recovery_required',json_encode($blocked['verification']));nativeExpect(!zfsmSanoidInventory($target)['snapshots'],'Replaced receiver was written');nativeExpect(zfsmReadIdentity($retained)['guid']===$guid,'Original receiver was not retained');
 return ['guid_observed_while_running'=>$guid,'resume_token_retained'=>true,'resume'=>$resumed['verified_outcome'],'replacement_guid'=>$replacement,'replacement_outcome'=>$blocked['verified_outcome'],'original_retained_at'=>$retained];
});
nativeCheck('target appearing after an absent-target review needs explicit ownership review',function()use($src,$dst){
 $target=$dst.'/unexpected';$r=reviewDefinition('c4',$src.'/send',$target);nativeCommand(['create','-o','canmount=off',$target]);$guid=zfsmReadIdentity($target)['guid'];$job=nativeJob('replication','c4');nativeExpect($job['state']==='recovery_required',json_encode($job['verification']));nativeExpect(!zfsmSanoidInventory($target)['snapshots'],'Unexpected target received snapshots');return ['outcome'=>$job['verified_outcome'],'target_guid'=>$guid,'snapshots'=>0];
});
file_put_contents($base.'/review-'.$variant.'.json',json_encode(['provenance'=>'Real native Linux flock, ZFS, Sanoid, Syncoid, owned cancellation; no VM reset. Only new review-* fixture datasets.','results'=>$results],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)."\n");
exit(array_filter($results,fn($r)=>$r['status']!=='PASS')?1:0);
